CREATE TABLE "Entities" (
    "Type" character varying(100) NOT NULL,
    "Key" character varying(200) NOT NULL,
    "Version" bigint NOT NULL,
    "Value" jsonb NOT NULL,
    CONSTRAINT "PK_Entities" PRIMARY KEY ("Type", "Key")
);

CREATE TABLE "Events" (
    "Position" bigint GENERATED BY DEFAULT AS IDENTITY,
    "StreamId" character varying(200) NOT NULL,
    "Sequence" bigint NOT NULL,
    "Type" character varying(200) NOT NULL,
    "Timestamp" timestamp with time zone NOT NULL,
    "Payload" jsonb NOT NULL,
    "Metadata" jsonb,
    CONSTRAINT "PK_Events" PRIMARY KEY ("Position")
);

CREATE UNIQUE INDEX "IX_Events_StreamId_Sequence" ON "Events" ("StreamId", "Sequence");
